// The Idle Adventure's Town Map (README: Idle Adventure, Town Map; the user's): FireRed's Kanto map, its places the run's
// towns, routes and dungeons, generated by tools/idle/town_map.py (data/gen1/town-map.ts). A town is travelled to
// (TRAVEL); a route or dungeon takes a Wild or Trainer grind (GRIND_AT); only those the run has reached.
import { areas, areaIndex, areaOpen, isTown, mapView } from './areas.js';
import { generation, perGeneration } from './generation.js';

/** The active generation's Town Map picture and its grid (Generation.townMapGrid). */
export const townMapGrid = () => generation().townMapGrid;

export interface TownMapPlace {
  /** Its map section (MAPSEC_, lower case). */
  section: string;
  /** Its name as the game's map shows it. */
  name: string;
  /** The run's areas there (areas()' ids): a town's every visit (Viridian City's two), a route's or dungeon's one. */
  areas: string[];
  /** Its cells on the grid, on the map's layer or the dungeons' (a dungeon's cell over a route's: the dungeon's first). */
  cells: [x: number, y: number, layer: 'map' | 'dungeon'][];
}

export const townMapPlaces = (): readonly TownMapPlace[] => generation().townMapPlaces;

/** The place at a grid cell, the dungeons' layer first, or null. */
export function townMapPlaceAt(x: number, y: number): TownMapPlace | null {
  const at = (layer: 'map' | 'dungeon') => townMapPlaces().find((p) => p.cells.some(([cx, cy, l]) => cx === x && cy === y && l === layer));
  return at('dungeon') ?? at('map') ?? null;
}

/**
 * The area a place stands for in a run that has reached `reached` (areas()' index): a town's latest visit reached (Viridian
 * City with its gym once there), a route's or dungeon's own (one off the main road once its `opens` is reached; a
 * main-road route's first, Route 21's before its tall grass: townMapAreas has both); null when none is reached yet.
 */
export function townMapArea(place: TownMapPlace, reached: number): number | null {
  const indices = townMapAreas(place, reached);
  if (!indices.length) return null;
  return isTown(areas()[indices[0]!]!) ? indices[indices.length - 1]! : indices[0]!;
}

/** Every area of a place a run that has reached `reached` can go to (a route's grinds are offered in each: Route 21's and its tall grass's). */
export function townMapAreas(place: TownMapPlace, reached: number): number[] {
  return place.areas.map(areaIndex).filter((i) => i >= 0 && areaOpen(i, reached));
}

/**
 * The place an area is on (a gym or a League room: its town's; grinding from a town: the town's); with the map the run
 * is on, the place of that map's section among the area's (Route 17 of Routes 16, 17 and 18).
 */
export function townMapPlaceOf(index: number, map?: string): TownMapPlace | null {
  let a = areas()[index];
  if (!a) return null;
  if (a.kind === 'gym' && a.town) a = areas()[areaIndex(a.town)]!;
  if (a.kind === 'league') a = areas().find((t) => isTown(t) && t.id === 'indigo-plateau') ?? a;
  const id = a.id;
  const section = map && mapView(map).section;
  return (section && townMapPlaces().find((p) => p.areas.includes(id) && p.section === section)) || (townMapPlaces().find((p) => p.areas.includes(id)) ?? null);
}

/**
 * A species' habitat on the Town Map (the Pokédex entry's Area, as the games' Pokédex shows it: the user's, 2026-11-06):
 * the places whose maps' wild tables have it (walked, surfed, fished, Rock Smash; the morning's, the night's, LeafGreen's
 * and SoulSilver's slots, and the extra slots of the gifts, trades and prizes, firered_data.py's), and the place of a
 * legendary Pokémon's area (WalkArea.legend). The active generation's; none where it has no wild Pokémon of it.
 */
export const habitat = (species: number): readonly TownMapPlace[] => habitats().get(species) ?? [];

const habitats = perGeneration((g) => {
  const sections = new Map<number, Set<string>>();
  const add = (species: number, section: string) => (sections.get(species) ?? sections.set(species, new Set()).get(species)!).add(section);
  for (const map of Object.values(g.maps)) {
    const table = g.encounters[map.encounters];
    if (!table || !map.section) continue;
    for (const slots of [table.land, table.water, table.fishing, table.rockSmash, table.oldRod, table.goodRod, table.superRod]) {
      if (!slots) continue;
      for (const list of [slots.mons, slots.extra, slots.morning, slots.night]) for (const [, , s] of list ?? []) add(s, map.section);
      for (const list of [slots.leafGreen, slots.soulSilver?.morning, slots.soulSilver?.day, slots.soulSilver?.night]) for (const [, , , s] of list ?? []) add(s, map.section);
    }
    if (table.nightFish) add(table.nightFish, map.section);
  }
  const out = new Map<number, TownMapPlace[]>();
  for (const [species, found] of sections) out.set(species, g.townMapPlaces.filter((p) => found.has(p.section)));
  for (const a of g.areas) {
    const legend = 'legend' in a ? a.legend : undefined;
    const place = legend && g.townMapPlaces.find((p) => p.areas.includes(a.id));
    if (!legend || !place) continue;
    const list = out.get(legend.species) ?? out.set(legend.species, []).get(legend.species)!;
    if (!list.includes(place)) list.push(place);
  }
  return out;
});
